import{experimentResult,sensor,series,parallel}from './el2-models.js?v=20261023-physicscomplete01';import{symbolGlyph}from './el1-figures.js?v=20261023-physicscomplete01';
const ink='#faf5ed',mint='#a9cabe',coral='#e7af97',dim='#a7bec6';const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const fmt=x=>Number(Number(x).toFixed(3));const T=(x,y,s,n=17,c=ink)=>`<text x="${x}" y="${y}" text-anchor="middle" fill="${c}" font-family="sans-serif" font-size="${n}">${esc(s)}</text>`;const L=(x,y,u,v,c=dim,w=3)=>`<path d="M${x} ${y}L${u} ${v}" fill="none" stroke="${c}" stroke-width="${w}"/>`;const D=(x,y,r=4,c=coral)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}"/>`;const B=(x,y,w,h,c='#264757')=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="12" fill="${c}" stroke="${dim}"/>`;export const el2SVG=(body,label)=>`<svg viewBox="0 0 560 480" role="img" aria-label="${esc(label)}">${body}</svg>`;
const meter=(x,y,letter)=>`<circle cx="${x}" cy="${y}" r="18" fill="#1a3545" stroke="${ink}" stroke-width="2"/>`+T(x,y+6,letter,20);
export function circuitPair({topology='series',V=6,R1=10,R2=20,progress=0,moving=false,revealed=true}={}){let r=topology==='series'?series(V,R1,R2):parallel(V,R1,R2),body=T(280,28,topology==='series'?'One path · common current · sharedpd':'Alternative paths · sharedpd · currents add',22)+`<path d="M245 100H90V320M315 100H470V320" fill="none" stroke="${mint}" stroke-width="4"/>`+symbolGlyph('cell',280,100,.68)+T(280,74,V+' V source',19)+meter(90,158,'A')+T(280,147,revealed?'Source I = '+fmt(r.I)+' A':'Predict source current',22);
if(topology==='series'){body+=L(90,320,162,320,mint,4)+L(278,320,332,320,mint,4)+L(448,320,470,320,mint,4)+symbolGlyph('resistor',220,320)+symbolGlyph('resistor',390,320)+T(220,280,'R₁ '+R1+' Ω',18)+T(390,280,'R₂ '+R2+' Ω',18)+T(220,361,'V₁ '+fmt(r.V1)+' V',18)+T(390,361,'V₂ '+fmt(r.V2)+' V',18)+T(280,209,'Rtotal = '+r.R+' Ω · same I throughout',18)+T(280,240,fmt(r.V1)+' + '+fmt(r.V2)+' = '+V+' V',19)+`<path d="M150 320V413H262M298 413H450V320" fill="none" stroke="${dim}" stroke-width="2"/>`+meter(280,413,'V')+T(280,452,'Voltmeter across group · group reading '+V+' V',15);if(moving)for(let j=0;j<7;j++){let x=100+((progress*r.I*3+j/7)%1)*360;body+=D(x,320);}}
else{body+=L(90,220,222,220,mint,4)+L(338,220,470,220,mint,4)+symbolGlyph('resistor',280,220)+L(90,320,126,320,mint,4)+L(174,320,222,320,mint,4)+L(338,320,470,320,mint,4)+symbolGlyph(r.open?'switch':'closed',150,320,.4)+symbolGlyph('resistor',280,320)+D(90,220,5,mint)+D(470,220,5,mint)+T(280,195,'R₁ '+R1+' Ω',16)+T(280,260,'Branch1: '+V+' V · '+fmt(r.I1)+' A',18)+T(280,297,r.open?'Branch2 open':'R₂ '+R2+' Ω',16)+T(280,360,r.open?'I₂ =0 · broken path':V+' V · '+fmt(r.I2)+' A',18)+T(280,406,fmt(r.I1)+' + '+fmt(r.I2)+' = '+fmt(r.I)+' A',22)+T(280,440,r.open?'One complete branch remains':'Total resistance below either branch resistance',15);if(moving){for(let j=0;j<5;j++){body+=D(100+((progress*r.I1*3+j/5)%1)*360,220,4,mint);if(!r.open)body+=D(100+((progress*r.I2*3+j/5)%1)*360,320,4,coral);}}}
body+=T(280,474,'Ideal source/resistors · conventional-current tracers, not electron speed or counts',12);return el2SVG(body,`${topology} ideal circuit: ${V} V, R1 = ${R1} ohms, R2 = ${r.open?'open':R2+'ohms'}, source current${fmt(r.I)}A. ${topology==='series'?'Common current; component voltages'+fmt(r.V1)+'V and'+fmt(r.V2)+'V add to source.':'Closed branches share sourcepd; branch currents'+fmt(r.I1)+'A and'+fmt(r.I2)+'A add to total. '+(r.open?'Open branch has a visible gap; no sourcepd is assigned across its isolated resistor.':'Both branches are closed.')} Meter in source series path. Tracer timing symbolic; parallel equivalent-resistance formula is not required.`);}
export function sensorFigure({kind='thermistor',a,b,progress=1,movie=false,revealed=true}={}){let stimulus=movie?(kind==='thermistor'?20+40*(1-Math.abs(2*progress-1)):100*(1-Math.abs(2*progress-1))):Number(a??(kind==='thermistor'?'20':'0')),V=Number(b||'2'),r=sensor(kind,stimulus,V),isT=kind==='thermistor',threshold=isT?'below40°C':'below index50',body=T(280,28,isT?'Temperature → sensor → controller → heater':'Illumination → sensor → controller → lamp',21)+B(45,83,190,160)+T(140,70,isT?fmt(stimulus)+'°C':'Light index '+fmt(stimulus),22)+symbolGlyph(isT?'thermistor':'ldr',140,149,.72)+T(140,213,'R = '+fmt(r.R)+' Ω',18)+L(240,160,316,160,coral,3)+B(320,100,190,125,'#294c5c')+T(415,133,'Controller',21)+T(415,163,'ON '+threshold,15)+T(415,194,'Chosen rule',15)+B(325,266,180,79,r.on?'#8a5e50':'#264452')+T(415,297,isT?'Heater':'Lamp',21)+T(415,326,r.on?'ON':'OFF',21)+L(415,225,415,261,coral,3)+T(280,405,revealed?V+' V · sensor I '+fmt(r.mA)+' mA':V+' V · predict sensor current / mA',22);
let xmin=isT?20:0,xmax=isT?60:100,maxR=isT?1000:10000,path='';for(let j=0;j<=40;j++){let s=xmin+(xmax-xmin)*j/40,v=sensor(kind,s,V);path+=(j?'L':'M')+(60+j*4.5)+' '+(350-v.R/maxR*80);}body+=L(60,350,245,350)+L(60,350,60,263)+`<path d="${path}" fill="none" stroke="${mint}" stroke-width="3"/>`+D(60+(stimulus-xmin)/(xmax-xmin)*180,350-r.R/maxR*80,5)+T(150,261,isT?'R / Ω (0–1000)':'R / Ω (0–10000)',12)+T(61,368,xmin,12)+T(240,368,xmax,12)+T(150,383,isT?'Temperature / °C':'Light index',13)+T(280,431,isT?'Measuring circuit: A in series; V across thermistor':'Measuring circuit: A in series; V across LDR',15)+T(280,451,'Sensor response ≠ chosen output · controller/power stage is a conceptual block',12)+T(280,474,'Original bounded curve and threshold · imposed stimulus, not a feedback simulation',12);return el2SVG(body,`${kind} original sensor model: stimulus${fmt(stimulus)}${isT?'°C':'light-index'}, ${V}V, resistance${fmt(r.R)}ohms, sensor current${fmt(r.mA)}mA. Controller chosen ON ${threshold}; output${r.on?'ON':'OFF'}. Increasing stimulus lowersR and increases current at fixedpd. Temperature/light trajectory is imposed, not generated by the output or a device calibration. Controller block omits its hardware and separate power supply details.`);}
export function circuitLearningFigure(o={}){if(o.concealed)return el2SVG(T(280,230,'Predict, then reveal evidence',24),'Evidence concealed until prediction');let k=(o.kind||'series').replace(/-(model|data)$/,'');if(['thermistor','ldr'].includes(k))return sensorFigure({...o,kind:k});let r=experimentResult(k,o.a||(k==='combinations'?'series':'6'),o.b||'10');return circuitPair({...r,...o,topology:r.topology});}
